svg.script:
(function () {
  var root = document.getElementById('a16p13-svg');
  if (!root) return;

  var vKicker = document.getElementById('a16p13-verdict-kicker');
  var vMain = document.getElementById('a16p13-verdict-main');
  var vSub = document.getElementById('a16p13-verdict-sub');
  var tooltip = document.getElementById('a16p13-tooltip');
  var tipBg = document.getElementById('a16p13-tip-bg');
  var tipTitle = document.getElementById('a16p13-tip-title');
  var tipBody = document.getElementById('a16p13-tip-body');

  var layerBtns = {
    '1': 'a16p13-btn-duplo',
    '2': 'a16p13-btn-triplo',
    '3': 'a16p13-btn-quad'
  };

  var layers = {
    '0': {
      kicker: 'LAB GENÉTICO · SÍNTESE',
      main: 'Monte o painel ou desmonte a ilusão do NIPT',
      sub: 'hCG em todos · NIPT ≥10 sem · ainda rastreio · não substitui US'
    },
    '1': {
      kicker: 'DUPLO · 11–14 SEM',
      main: 'hCG + PAPP-A · via cedo com US',
      sub: 'Dois marcadores no 1º trimestre · base da pirâmide sérica'
    },
    '2': {
      kicker: 'TRIPLO',
      main: 'hCG + AFP + estriol',
      sub: 'Sangue depois também aceitável · hCG permanece'
    },
    '3': {
      kicker: 'QUÁDRUPLO',
      main: 'Triplo + inibina A',
      sub: 'Painel sérico mais completo · ainda rastreio, não diagnóstico'
    }
  };

  var illusionOff = {
    kicker: 'ILUSÃO DESMONTADA',
    main: 'NIPT tem DNA fetal e AINDA é rastreio',
    sub: 'Avalia trissomias (± sexagem) · não substitui US · não é cariótipo'
  };

  function clearActive() {
    var btns = root.querySelectorAll('.a16p13-btn');
    for (var i = 0; i < btns.length; i++) btns[i].classList.remove('a16p13-active');
  }

  function setLayer(n) {
    var key = String(n);
    if (!layers[key]) key = '0';
    root.setAttribute('data-layer', key);
    clearActive();
    if (layerBtns[key]) {
      var b = document.getElementById(layerBtns[key]);
      if (b) b.classList.add('a16p13-active');
    }
    refreshVerdict();
  }

  function setIllusion(state) {
    root.setAttribute('data-illusion', state);
    var btn = document.getElementById('a16p13-btn-illusion');
    if (btn) {
      if (state === 'off') btn.classList.add('a16p13-active');
      else btn.classList.remove('a16p13-active');
    }
    refreshVerdict();
  }

  function setPath(p) {
    root.setAttribute('data-path', p || 'none');
    if (p === 'cedo' || p === 'tarde') {
      if (vKicker) vKicker.textContent = 'ESCOLHA PRÁTICA';
      if (vMain) {
        vMain.textContent = p === 'cedo'
          ? 'Cedo: US + duplo (11–14) · aceitável'
          : 'Depois: triplo ou quádruplo · aceitável';
      }
      if (vSub) vSub.textContent = 'As duas vias de sangue rastreiam · nenhuma fecha diagnóstico sozinha';
    } else {
      refreshVerdict();
    }
  }

  function refreshVerdict() {
    var ill = root.getAttribute('data-illusion');
    var layer = root.getAttribute('data-layer') || '0';
    if (ill === 'off') {
      if (vKicker) vKicker.textContent = illusionOff.kicker;
      if (vMain) vMain.textContent = illusionOff.main;
      if (vSub) vSub.textContent = illusionOff.sub;
      return;
    }
    var cfg = layers[layer] || layers['0'];
    if (vKicker) vKicker.textContent = cfg.kicker;
    if (vMain) vMain.textContent = cfg.main;
    if (vSub) vSub.textContent = cfg.sub;
  }

  function bindLayer(id, n) {
    var el = document.getElementById(id);
    if (!el) return;
    var run = function () { setLayer(n); };
    el.addEventListener('click', run);
    el.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); run(); }
    });
  }
  bindLayer('a16p13-btn-duplo', 1);
  bindLayer('a16p13-btn-triplo', 2);
  bindLayer('a16p13-btn-quad', 3);

  var toggleIll = function () {
    var cur = root.getAttribute('data-illusion') || 'on';
    setIllusion(cur === 'on' ? 'off' : 'on');
  };
  var illBtn = document.getElementById('a16p13-btn-illusion');
  if (illBtn) {
    illBtn.addEventListener('click', toggleIll);
    illBtn.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleIll(); }
    });
  }
  var mythNodes = root.querySelectorAll('.a16p13-illusion');
  for (var mi = 0; mi < mythNodes.length; mi++) {
    mythNodes[mi].addEventListener('click', toggleIll);
    mythNodes[mi].addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleIll(); }
    });
  }

  var resetBtn = document.getElementById('a16p13-btn-reset');
  if (resetBtn) {
    var doReset = function () {
      setLayer(0);
      setIllusion('on');
      setPath('none');
    };
    resetBtn.addEventListener('click', doReset);
    resetBtn.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); doReset(); }
    });
  }

  function bindPath(id, p) {
    var el = document.getElementById(id);
    if (!el) return;
    var run = function () { setPath(p); };
    el.addEventListener('click', run);
    el.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); run(); }
    });
  }
  bindPath('a16p13-path-cedo', 'cedo');
  bindPath('a16p13-path-tarde', 'tarde');

  // Click strata also sets layer
  var strata = [
    { sel: '.a16p13-stratum-d', n: 1 },
    { sel: '.a16p13-stratum-t', n: 2 },
    { sel: '.a16p13-stratum-q', n: 3 }
  ];
  for (var s = 0; s < strata.length; s++) {
    (function (item) {
      var nodes = root.querySelectorAll(item.sel);
      for (var i = 0; i < nodes.length; i++) {
        nodes[i].addEventListener('click', function () { setLayer(item.n); });
        nodes[i].addEventListener('keydown', function (e) {
          if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setLayer(item.n); }
        });
      }
    })(strata[s]);
  }

  function wrapBody(body, maxChars) {
    var words = (body || '').split(/\s+/);
    var lines = [];
    var cur = '';
    for (var i = 0; i < words.length; i++) {
      var trial = cur ? cur + ' ' + words[i] : words[i];
      if (trial.length > maxChars && cur) {
        lines.push(cur);
        cur = words[i];
      } else {
        cur = trial;
      }
    }
    if (cur) lines.push(cur);
    return lines.slice(0, 3);
  }

  function showTip(title, body, clientX, clientY) {
    if (!tooltip || !tipTitle || !tipBody) return;
    tipTitle.textContent = title || '';
    while (tipBody.firstChild) tipBody.removeChild(tipBody.firstChild);
    var lines = wrapBody(body, 44);
    for (var i = 0; i < lines.length; i++) {
      var t = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
      t.setAttribute('x', '12');
      t.setAttribute('dy', i === 0 ? '0' : '14');
      t.textContent = lines[i];
      tipBody.appendChild(t);
    }
    var th = 36 + Math.max(1, lines.length) * 14;
    if (tipBg) {
      tipBg.setAttribute('width', '300');
      tipBg.setAttribute('height', String(th));
    }
    tooltip.classList.add('a16p13-show');
    moveTip(clientX, clientY);
  }

  function moveTip(clientX, clientY) {
    if (!tooltip || !tooltip.classList.contains('a16p13-show')) return;
    var ctm = root.getScreenCTM();
    if (!ctm) return;
    var pt = root.createSVGPoint();
    pt.x = clientX;
    pt.y = clientY;
    var sp = pt.matrixTransform(ctm.inverse());
    var x = sp.x + 14;
    var y = sp.y + 14;
    var vb = root.viewBox.baseVal;
    var maxX = (vb && vb.width ? vb.width : 1000) - 312;
    var maxY = (vb && vb.height ? vb.height : 900) - 90;
    if (x > maxX) x = sp.x - 314;
    if (y > maxY) y = sp.y - 90;
    if (x < 8) x = 8;
    if (y < 8) y = 8;
    tooltip.setAttribute('transform', 'translate(' + x + ',' + y + ')');
  }

  function hideTip() {
    if (tooltip) tooltip.classList.remove('a16p13-show');
  }

  var tips = root.querySelectorAll('[data-tip-title]');
  for (var t = 0; t < tips.length; t++) {
    (function (el) {
      el.addEventListener('mouseenter', function (e) {
        showTip(el.getAttribute('data-tip-title'), el.getAttribute('data-tip-body'), e.clientX, e.clientY);
      });
      el.addEventListener('mousemove', function (e) { moveTip(e.clientX, e.clientY); });
      el.addEventListener('mouseleave', hideTip);
      el.addEventListener('focus', function () {
        var r = el.getBoundingClientRect();
        showTip(el.getAttribute('data-tip-title'), el.getAttribute('data-tip-body'), r.left + r.width / 2, r.top);
      });
      el.addEventListener('blur', hideTip);
    })(tips[t]);
  }

  root.addEventListener('mousemove', function (e) { moveTip(e.clientX, e.clientY); });

  // Initial: show illusion ON so "desmontar" teaches; layer 0
  setLayer(0);
  setIllusion('on');
  setPath('none');
})();
